), blu, $0, sgr) } !kl { printf("%s%s%s
", wht, $0, sgr) } ' <<< "$@" } J'ai vu que l'utilisation de bask avec un appel au code awk ne met pas en évidence la syntaxe awk. Il serait hautement souhaitable de mettre en évidence le code awk joint en guillemets simples. prax () { ## Contrôles de la fonction couleur d'impression awk -v fgb="$blu" -v fgw="$wht" -v rst="$sgr" \ 'BEGIN { "tput sgr0"="& getline sgr "tput bold; tput setaf 15"="& getline wht "tput bold; tput bold; tput setaf 39"="& getline blu } /Code:$/ { kl=1 ; suivant } !NF { kl=0 } kl { printf("%s%s%s
), blu, $0, sgr)} !kl { printf("%s%s%s
", wht, $0, sgr)} ' << "$@" }

