>> // Vous pouvez attribuer des permissions supplémentaires à des applications web particulières par
>> // ajouter ici des entrées « grant » supplémentaires, en fonction de la base de code pour cela
>> // application, /WEB-INF/classes/, ou /WEB-INF/lib/ jar files.
>> //
>> // Différentes permissions peuvent être accordées aux pages JSP, classes chargées à partir
>> // le répertoire /WEB-INF/classes/, tous les fichiers jar dans le répertoire /WEB-INF/lib/
>> // répertoire, ou même à des fichiers jar individuels dans le répertoire /WEB-INF/lib/.
>> //
>> // Par exemple, supposons que l'application standard "exemples"
>> // inclus un pilote JDBC qui a besoin pour établir une connexion réseau au
>> // base de données correspondante et utilisé le taglib de racle pour obtenir le temps
>> // le serveur web NOAA.  Vous pourriez créer une entrée "subvention" comme ceci:
>> //
>> // Les permissions accordées au répertoire contextuel racine s'appliquent aux pages JSP.
>> // code de subventionBase "fichier:${catalina.base}/webapps/exemples/-" {
>> // permission java.net.SocketPermission "dbhost.mycompany.com:5432", "connect";
>> // permission java.net.SocketPermission "*.noaa.gov:80", "connect";
>> // };
>> //
>> // Les autorisations accordées au répertoire contexte WEB-INF/classes
>> // code de subventionBase "fichier:${catalina.base}/webapps/exemples/WEB-INF/classes/-" {
>> // };
>> //
>> // La permission accordée à votre pilote JDBC
>> // code de subventionBase "jar:file:${catalina.base}/webapps/exemples/WEB-INF/lib/driver.jar!/-" {
>> // permission java.net.SocketPermission "dbhost.mycompany.com:5432", "connect";
>> // };
>> // La permission accordée au taglib de racler
>> // code de subventionBase "jar:file:${catalina.base}/webapps/exemples/WEB-INF/lib/scrape.jar!/-" {
>> // permission java.net.SocketPermission "*.noaa.gov:80", "connect";
>> // };
>>
>> // Pour accorder des autorisations pour des applications Web utilisant des fichiers WAR emballés, utilisez le
>> // Régime spécifique de WAR url.
>> //
>> // Les autorisations accordées à l'ensemble de l'application web
>> // code de subventionBase "war:file:${catalina.base}/webapps/examples.war*/-" {
>> // };
>> //
>> // Les autorisations accordées à un JAR spécifique
>> // code de subventionBase "war:file:${catalina.base}/webapps/examples.war*/WEB-INF/lib/foo.jar" {
>> // };
